@push('scripts')<script>(()=>{const input=document.getElementById('csv'),drop=document.getElementById('csvDropzone'),card=document.getElementById('selectedFile'),button=document.getElementById('continueButton');const update=()=>{const f=input.files[0];card.hidden=!f;drop.hidden=!!f;button.disabled=!f;if(f){document.getElementById('selectedFileName').textContent=f.name;document.getElementById('selectedFileSize').textContent=(f.size/1048576).toFixed(2)+' MB'}};input.addEventListener('change',update);document.getElementById('removeFile').onclick=()=>{input.value='';update()};const coverage=document.getElementById('coverage'),program=document.getElementById('programField');const toggle=()=>program.hidden=coverage.value!=='specific';coverage.onchange=toggle;toggle();document.getElementById('csvUploadForm').onsubmit=()=>{button.disabled=true;button.textContent='Validating…'}})();</script>@endpush